/// <summary>
/// Supplies sample token values for the label preview. Provides a fixed map for record-less
/// tokens and type-aware values for record-qualified tokens, so a layout renders fully
/// populated even when no live record is available.
/// </summary>
public final class AAXWHSLabelPreviewSampleData
{
}

Method.Source:
/// <summary>
/// Builds the sample token map used to substitute record-less placeholders during preview.
/// </summary>
/// <returns>A <c>Map</c> of <c>Types::String</c> keys and values holding the sample token values.</returns>
public static Map sampleParameterMap()
{
    Map sampleMap = new Map(Types::String, Types::String);
    str today = AAXWHSLabelPreviewSampleData::sampleDateString();

    // Identifiers with realistic lengths
    sampleMap.insert('OrderNum',       'PO123456');
    sampleMap.insert('PurchId',        'PO123456');
    sampleMap.insert('LicensePlateId', 'LP000123');
    sampleMap.insert('ItemId',         'A0001');
    sampleMap.insert('WorkId',         'WK000123');
    sampleMap.insert('Qty',            '12');

    // Dates default to today
    sampleMap.insert('Date',           today);
    sampleMap.insert('TransDate',      today);
    sampleMap.insert('DeliveryDate',   today);

    return sampleMap;
}

/// <summary>
/// Returns today's date formatted as yyyy-MM-dd so qualified and unqualified date tokens match
/// in the preview.
/// </summary>
/// <returns>Today's date as a yyyy-MM-dd string.</returns>
public static str sampleDateString()
{
    return date2str(
        systemDateGet(),
        321,
        DateDay::Digits2,
        DateSeparator::Hyphen,
        DateMonth::Digits2,
        DateSeparator::Hyphen,
        DateYear::Digits4,
        DateFlags::None);
}

/// <summary>
/// Produces a sample value for a record-qualified token field so the token resolves even when
/// the referenced table has no live record.
/// </summary>
/// <param name = "_recordName">The token record name, optionally carrying a trailing _&lt;digits&gt; datasource alias suffix.</param>
/// <param name = "_fieldName">The token field name.</param>
/// <returns>A type-aware sample value when the record resolves to a real table field; otherwise a value derived from the field name. Never empty.</returns>
public static str sampleValueForField(str _recordName, str _fieldName)
{
    TableId tableId = AAXWHSLabelPreviewSampleData::resolveTableId(_recordName);

    if (tableId)
    {
        DictTable dictTable = new DictTable(tableId);
        FieldId   fieldId   = dictTable ? dictTable.fieldName2Id(_fieldName) : 0;

        if (fieldId)
        {
            return AAXWHSLabelPreviewSampleData::sampleValueForDictField(tableId, fieldId, _fieldName);
        }
    }

    // Fall back to the field name heuristic
    return AAXWHSLabelPreviewSampleData::sampleValueByNameHeuristic(_fieldName, 0);
}

/// <summary>
/// Resolves a token record name to a table id, also trying the name without a trailing
/// _&lt;digits&gt; datasource alias suffix.
/// </summary>
/// <param name = "_recordName">The token record name.</param>
/// <returns>The matching <c>TableId</c>, or 0 when neither form is a table.</returns>
private static TableId resolveTableId(str _recordName)
{
    TableId tableId;

    if (!_recordName)
    {
        return 0;
    }

    // Try the record name as a table name
    tableId = tableName2Id(_recordName);
    if (tableId)
    {
        return tableId;
    }

    // Strip a trailing datasource alias suffix such as _1
    System.Text.RegularExpressions.Match aliasMatch =
        System.Text.RegularExpressions.Regex::Match(_recordName, @'^(.*?)_[0-9]+$');
    if (aliasMatch.Success)
    {
        str baseName = aliasMatch.Groups.get_Item(1).Value;
        if (baseName && baseName != _recordName)
        {
            tableId = tableName2Id(baseName);
        }
    }

    return tableId;
}

/// <summary>
/// Produces a type-aware sample value for a field that is known to exist on a real table.
/// </summary>
/// <param name = "_tableId">The owning table id.</param>
/// <param name = "_fieldId">The field id (known non-zero).</param>
/// <param name = "_fieldName">The field name, used for the string value heuristics.</param>
/// <returns>A sample value for the field's base type. Never empty.</returns>
private static str sampleValueForDictField(TableId _tableId, FieldId _fieldId, str _fieldName)
{
    DictField dictField = new DictField(_tableId, _fieldId);
    Types     baseType  = dictField.baseType();

    switch (baseType)
    {
        case Types::Date:
            return AAXWHSLabelPreviewSampleData::sampleDateString();

        case Types::UtcDateTime:
            return DateTimeUtil::toStr(DateTimeUtil::utcNow());

        case Types::Time:
            return time2str(43200, TimeSeparator::Colon, TimeFormat::Hour24); // 12:00:00

        case Types::Integer:
        case Types::Int64:
            return '12';

        case Types::Real:
            return '12.00';

        case Types::Enum:
            return AAXWHSLabelPreviewSampleData::sampleEnumLabel(dictField);

        case Types::Guid:
            return guid2str(newGuid());

        case Types::String:
        case Types::VarString:
            return AAXWHSLabelPreviewSampleData::sampleValueByNameHeuristic(_fieldName, dictField.stringLen());

        default:
            // Container and unknown types use a printable placeholder
            return AAXWHSLabelPreviewSampleData::sampleValueByNameHeuristic(_fieldName, dictField.stringLen());
    }
}

/// <summary>
/// Returns the first non-zero enum label for an enum field so enum tokens render a meaningful
/// value.
/// </summary>
/// <param name = "_dictField">The enum <c>DictField</c>.</param>
/// <returns>A human-readable enum label, or '1' when none can be resolved.</returns>
private static str sampleEnumLabel(DictField _dictField)
{
    EnumId enumId = _dictField.enumId();
    if (!enumId)
    {
        return '1';
    }

    DictEnum dictEnum = new DictEnum(enumId);
    int      valueCount = dictEnum.values();
    str      firstLabel = '';
    int      i;

    for (i = 0; i < valueCount; i++)
    {
        str label = dictEnum.index2Label(i);
        if (i == 0)
        {
            firstLabel = label;
        }

        // Prefer the first non-zero element since zero is usually a placeholder
        if (dictEnum.index2Value(i) != 0 && label)
        {
            return label;
        }
    }

    return firstLabel ? firstLabel : '1';
}

/// <summary>
/// Produces a sample string value from the field name alone, trimmed to an optional maximum
/// length.
/// </summary>
/// <param name = "_fieldName">The token field name.</param>
/// <param name = "_maxLen">The maximum string length; 0 means no trimming.</param>
/// <returns>A sample string derived from the field name. Never empty.</returns>
private static str sampleValueByNameHeuristic(str _fieldName, int _maxLen)
{
    str lower = strLwr(_fieldName);
    str result;

    switch (true)
    {
        case (strScan(lower, 'license', 1, strLen(lower)) > 0
              || strScan(lower, 'plate', 1, strLen(lower)) > 0):
            result = 'LP000123';
            break;

        case (strScan(lower, 'order', 1, strLen(lower)) > 0
              || strScan(lower, 'purch', 1, strLen(lower)) > 0):
            result = 'PO123456';
            break;

        case (strScan(lower, 'work', 1, strLen(lower)) > 0):
            result = 'WK000123';
            break;

        case (strScan(lower, 'item', 1, strLen(lower)) > 0):
            result = 'A0001';
            break;

        case (strScan(lower, 'date', 1, strLen(lower)) > 0):
            result = AAXWHSLabelPreviewSampleData::sampleDateString();
            break;

        case (strScan(lower, 'qty', 1, strLen(lower)) > 0
              || strScan(lower, 'quantity', 1, strLen(lower)) > 0
              || strScan(lower, 'weight', 1, strLen(lower)) > 0):
            result = '12';
            break;

        case (strScan(lower, 'id', 1, strLen(lower)) > 0
              || strScan(lower, 'num', 1, strLen(lower)) > 0
              || strScan(lower, 'code', 1, strLen(lower)) > 0
              || strScan(lower, 'ref', 1, strLen(lower)) > 0):
            result = 'SMP000123';
            break;

        case (strScan(lower, 'name', 1, strLen(lower)) > 0
              || strScan(lower, 'descr', 1, strLen(lower)) > 0
              || strScan(lower, 'text', 1, strLen(lower)) > 0):
            result = strFmt('Sample %1', _fieldName);
            break;

        default:
            result = 'SAMPLE';
            break;
    }

    // Trim to the field size when known
    if (_maxLen > 0 && strLen(result) > _maxLen)
    {
        result = subStr(result, 1, _maxLen);
    }

    return result;
}

/// <summary>
/// Builds a named parameter map for one record name with a sample value for each field
/// referenced by that record's tokens.
/// </summary>
/// <param name = "_recordName">The token record name used as the map name.</param>
/// <param name = "_fieldNames">A <c>Set</c> of the field names referenced for the record.</param>
/// <returns>A <c>Map</c> of field names to sample values, or <c>null</c> when there are no field names.</returns>
public static Map sampleMapForRecordTokens(str _recordName, Set _fieldNames)
{
    if (!_fieldNames || _fieldNames.empty())
    {
        return null;
    }

    Map sampleMap = new Map(Types::String, Types::String);
    SetEnumerator se = _fieldNames.getEnumerator();

    while (se.moveNext())
    {
        str fieldName = se.current();
        if (fieldName && !sampleMap.exists(fieldName))
        {
            sampleMap.insert(fieldName, AAXWHSLabelPreviewSampleData::sampleValueForField(_recordName, fieldName));
        }
    }

    return sampleMap;
}
